/* SEPA Course service worker. Generated by tools/build-web.js from tools/sw.template.js: edit the template, not web/sw.js.
   Scope: /sepa-course/ only. Cache names start with "sep-".
   - Pages, scripts, styles, manifest: network first (always fresh when online), the cached copy when offline.
   - Images, sound, fonts: cache first; Range requests are answered from the cache so audio can seek offline.
   - Calls to the Apps Script API (POST, another site) are never touched. */
const VERSION = 'd84e6cb29d';
const SHELL = 'sep-shell-' + VERSION;
const STATIC = 'sep-static-v1';
const CORE = ['./', './index.html', './app.js', './manifest.webmanifest', './icon-192.png', './icon-128.png'];

self.addEventListener('install', e => {
  e.waitUntil(caches.open(SHELL).then(c => Promise.all(CORE.map(u => fetch(u, { cache: 'no-cache' }).then(r => r.ok && c.put(u, r)).catch(() => {})))).then(() => self.skipWaiting()));
});

self.addEventListener('activate', e => {
  e.waitUntil(caches.keys().then(keys => Promise.all(keys.filter(k => k.startsWith('sep-shell-') && k !== SHELL).map(k => caches.delete(k)))).then(() => self.clients.claim()));
});

const MEDIA = /\.(png|jpe?g|gif|webp|svg|ico|mp3|m4a|ogg|oga|wav|webm|aac|woff2?)$/i;
const FONT_HOSTS = ['fonts.googleapis.com', 'fonts.gstatic.com'];

self.addEventListener('fetch', e => {
  const req = e.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (FONT_HOSTS.includes(url.hostname)) return e.respondWith(cacheFirst(req));
  if (url.origin !== location.origin || !url.pathname.startsWith(new URL(self.registration.scope).pathname)) return;
  if (url.pathname.includes('/sep-media/')) return;   // recordings: the page keeps these itself
  if (MEDIA.test(url.pathname) || req.destination === 'image' || req.destination === 'audio') return e.respondWith(cacheFirst(req));
  e.respondWith(networkFirst(req));
});

async function networkFirst(req) {
  const cache = await caches.open(SHELL);
  try {
    const res = await fetch(req, { cache: 'no-cache' });
    if (res.ok) cache.put(req, res.clone());
    return res;
  } catch (err) {
    const hit = await cache.match(req, { ignoreSearch: true }) || (req.mode === 'navigate' && (await cache.match('./index.html') || await cache.match('./')));
    if (hit) return hit;
    throw err;
  }
}

async function cacheFirst(req) {
  const cache = await caches.open(STATIC);
  const range = req.headers.get('range');
  let hit = await cache.match(req.url);
  if (!hit) {
    const res = await fetch(range ? new Request(req.url, { mode: req.mode === 'navigate' ? 'same-origin' : req.mode, credentials: req.credentials }) : req);
    if (!res.ok && res.type !== 'opaque') return res;
    await cache.put(req.url, res.clone());
    hit = res;
    if (!range) return res;
    hit = await cache.match(req.url) || res;
  }
  if (!range) return hit;
  return rangeResponse(hit, range);
}

async function rangeResponse(res, range) {
  const buf = await res.arrayBuffer(), size = buf.byteLength;
  const m = /bytes=(\d*)-(\d*)/.exec(range) || [];
  let start = m[1] ? parseInt(m[1], 10) : 0, end = m[2] ? parseInt(m[2], 10) : size - 1;
  if (!m[1] && m[2]) { start = Math.max(0, size - parseInt(m[2], 10)); end = size - 1; }
  if (start >= size || start > end) return new Response(null, { status: 416, headers: { 'Content-Range': 'bytes */' + size } });
  end = Math.min(end, size - 1);
  return new Response(buf.slice(start, end + 1), { status: 206, headers: {
    'Content-Type': res.headers.get('Content-Type') || 'application/octet-stream',
    'Content-Range': 'bytes ' + start + '-' + end + '/' + size,
    'Content-Length': String(end - start + 1), 'Accept-Ranges': 'bytes' } });
}
